
const $ = id => document.getElementById(id);
const state = {
  type:'invoice', docNo:'', docDate:'', billToName:'', billToInfo:'', billTo:'', poNumber:'N/A', doNumber:'N/A', deliveryTerm:'N/A', paymentTerm:'N/A',
  toName:'', location:'', delivery:0, sharedDelivery:0,
  notes:'Validity 14 days from the quotation date.\nDelivery within 2 – 12 weeks.',
  receiptNormalText:'All prices are quoted in Ringgit Malaysia (RM).',
  receiptBoldText:'Thank you for your business.',
  items:[{description:'',qty:0,unitPrice:0}],
  documents:{}
};


const config = {
  invoice:{title:'INVOICE', label:'Invoice', prefix:'3D-INV/UTHM/26/0000'},
  quotation:{title:'QUOTATION', label:'Quotation', prefix:'3D-QT/UTHM/26/0000'},
  do:{title:'DELIVERY ORDER', label:'D.O', prefix:'3D-DO/UTHM/26/0000'},
  receipt:{title:'RECEIPT', label:'Receipt', prefix:'3D-RC/UTHM/26/0000'}
};

function today(){const d=new Date();return d.toISOString().slice(0,10)}
function init(){
  state.docDate=today();
  state.docNo=config.invoice.prefix;
  ensureDocumentStates();
  restoreDocument(state.type);
  syncForm();
  render();
}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function money(n){return 'RM'+Number(n||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}
function dateText(v){if(!v)return '';const [y,m,d]=v.split('-');return `${d}/${m}/${y}`}
function docPrefix(type){return config[type].prefix}

function defaultDocument(type){
  const base={
    type,
    docNo:config[type].prefix,
    docDate:today(),
    billToName:'',
    billToInfo:'',
    billTo:'',
    poNumber:'N/A',
    doNumber:'N/A',
    deliveryTerm:'N/A',
    paymentTerm:'N/A',
    toName:'',
    location:'',
    delivery:0,
    notes:type==='quotation'?'Validity 14 days from the quotation date.\nDelivery within 2 – 12 weeks.':'',
    receiptNormalText:type==='receipt'?'All prices are quoted in Ringgit Malaysia (RM).':'',
    receiptBoldText:type==='receipt'?'Thank you for your business.':'',
    items:type==='do'
      ? [{description:'',qty:0}]
      : [{description:'',qty:0,unitPrice:0}]
  };
  return base;
}

function ensureDocumentStates(){
  if(!state.documents || typeof state.documents!=='object' || Array.isArray(state.documents)) state.documents={};
  for(const type of Object.keys(config)){
    const existing=state.documents[type];
    if(!existing){
      state.documents[type]=defaultDocument(type);
    }else{
      const def=defaultDocument(type);
      state.documents[type]=Object.assign(def,existing,{type});
      if(!Array.isArray(state.documents[type].items) || !state.documents[type].items.length){
        state.documents[type].items=def.items;
      }
    }
  }
  // Delivery is a single shared value across all document types. Migrate
  // older saved data by taking the currently selected document's value when
  // available, then propagate that shared value to every document state.
  if(!Object.prototype.hasOwnProperty.call(state,'sharedDelivery') || !Number.isFinite(Number(state.sharedDelivery))){
    const selectedDelivery=Number(state.documents[state.type||'invoice']?.delivery);
    state.sharedDelivery=Number.isFinite(selectedDelivery)?selectedDelivery:0;
  }
  state.sharedDelivery=Number(state.sharedDelivery||0);
  for(const type of Object.keys(config)){
    state.documents[type].delivery=state.sharedDelivery;
  }

  // Migrate the original single-document state into the selected document.
  const selected=state.documents[state.type];
  if(state.docNo || state.docDate || state.billToName || state.billToInfo ||
     state.billTo || (Array.isArray(state.items) && state.items.some(i=>i.description || Number(i.qty) || Number(i.unitPrice))) ||
     state.poNumber!=='N/A' || state.doNumber!=='N/A' || state.deliveryTerm!=='N/A' || state.paymentTerm!=='N/A'){
    Object.assign(selected,{
      type:state.type,
      docNo:state.docNo||selected.docNo,
      docDate:state.docDate||selected.docDate,
      billToName:state.billToName||selected.billToName,
      billToInfo:state.billToInfo||selected.billToInfo,
      billTo:state.billTo||selected.billTo,
      poNumber:state.poNumber||selected.poNumber,
      doNumber:state.doNumber||selected.doNumber,
      deliveryTerm:state.deliveryTerm||selected.deliveryTerm,
      paymentTerm:state.paymentTerm||selected.paymentTerm,
      toName:state.toName||selected.toName,
      location:state.location||selected.location,
      delivery:Number.isFinite(Number(state.sharedDelivery))?Number(state.sharedDelivery):(Number.isFinite(Number(state.delivery))?Number(state.delivery):selected.delivery),
      notes:state.notes!=null?state.notes:selected.notes,
      receiptNormalText:state.receiptNormalText!=null?state.receiptNormalText:selected.receiptNormalText,
      receiptBoldText:state.receiptBoldText!=null?state.receiptBoldText:selected.receiptBoldText,
      items:Array.isArray(state.items)&&state.items.length?JSON.parse(JSON.stringify(state.items)):selected.items
    });
  }
}

function snapshotCurrentDocument(){
  return {
    type:state.type,
    docNo:state.docNo,
    docDate:state.docDate,
    billToName:state.billToName,
    billToInfo:state.billToInfo,
    billTo:state.billTo,
    poNumber:state.poNumber,
    doNumber:state.doNumber,
    deliveryTerm:state.deliveryTerm,
    paymentTerm:state.paymentTerm,
    toName:state.toName,
    location:state.location,
    delivery:Number(state.delivery||0),
    notes:state.notes||'',
    receiptNormalText:state.receiptNormalText||'',
    receiptBoldText:state.receiptBoldText||'',
    items:JSON.parse(JSON.stringify(state.items||[]))
  };
}

function saveCurrentDocument(){
  ensureDocumentStates();
  if(Number.isFinite(Number(state.sharedDelivery))){
    state.delivery=Number(state.sharedDelivery);
  }
  state.documents[state.type]=snapshotCurrentDocument();
  for(const type of Object.keys(config)) state.documents[type].delivery=Number(state.sharedDelivery||0);
}

function syncSharedDelivery(value){
  const v=Number(value||0);
  state.delivery=v;
  state.sharedDelivery=v;
  for(const type of Object.keys(config)){
    const doc=state.documents[type] || (state.documents[type]=defaultDocument(type));
    doc.delivery=v;
  }
}

function restoreDocument(type){
  ensureDocumentStates();
  const d=state.documents[type]||defaultDocument(type);
  Object.assign(state,JSON.parse(JSON.stringify(d)),{type});
  if(!Array.isArray(state.items) || !state.items.length){
    state.items=defaultDocument(type).items;
  }
}

function syncForm(){
  if(!state.billToName && !state.billToInfo && state.billTo){
    const lines=String(state.billTo).split(/\r?\n/);
    state.billToName=lines.shift()||'';
    state.billToInfo=lines.join('\n');
  }
  $('docType').value=state.type;
  $('docNo').value=state.docNo||config[state.type].prefix;
  $('docDate').value=state.docDate||today();
  $('billToName').value=state.billToName||'';
  $('billToInfo').value=state.billToInfo||'';
  $('poNumber').value=state.poNumber||'N/A';
  $('doNumber').value=state.doNumber||'N/A';
  $('deliveryTerm').value=state.deliveryTerm||'N/A';
  $('paymentTerm').value=state.paymentTerm||'N/A';
  $('delivery').value=Number(state.sharedDelivery||state.delivery||0);
  const normalizedNotes=String(state.notes||'').replace(/\\n/g,'\n');
  state.notes=normalizedNotes;
  $('notes').value=normalizedNotes;
  $('receiptNormalText').value=state.receiptNormalText||'';
  $('receiptBoldText').value=state.receiptBoldText||'';
  updateFields();
  renderItemsEditor();
}

function updateFields(){
  const t=state.type;
  $('docNoLabel').textContent=config[t].label+' Number'; $('dateLabel').textContent=config[t].label+' Date';
  $('invoiceFields').style.display=t==='invoice'?'block':'none';
  $('itemsSection').style.display='block'; $('deliveryEditor').style.display=t==='do'?'none':'grid';
  $('notesSection').style.display=(t==='invoice'||t==='quotation'||t==='receipt')?'block':'none';
  $('standardNotesEditor').style.display=(t==='receipt')?'none':'block';
  $('receiptNotesEditor').style.display=(t==='receipt')?'block':'none';
  $('notesHeading').textContent=t==='receipt'?'Notes / Terms':'Notes / Terms';
  $('addItemBtn').style.display=t==='do'?'none':'block';
}
function renderItemsEditor(){
  const ed=$('itemsEditor'); ed.innerHTML='';
  state.items.forEach((it,i)=>{
    const wrap=document.createElement('div'); wrap.className='item-edit';
    if(state.type==='do'){
      wrap.innerHTML=`<div class="rowhead"><span>Item ${i+1}</span>${state.type!=='do' && state.items.length>1?`<button class="mini" data-remove="${i}">Remove</button>`:''}</div><label>Description</label><input data-field="description" data-index="${i}" value="${esc(it.description)}"><label>Qty</label><input type="number" step="any" data-field="qty" data-index="${i}" value="${Number(it.qty||0)}">`;
    }else{
      wrap.innerHTML=`<div class="rowhead"><span>Item ${i+1}</span>${state.type!=='do' && state.items.length>1?`<button class="mini" data-remove="${i}">Remove</button>`:''}</div><label>Description</label><input data-field="description" data-index="${i}" value="${esc(it.description)}"><div class="grid2"><div><label>Qty</label><input type="number" step="any" data-field="qty" data-index="${i}" value="${Number(it.qty||0)}"></div><div><label>Unit Price (RM)</label><input type="number" step="0.01" min="0" data-field="unitPrice" data-index="${i}" value="${Number(it.unitPrice||0)}"></div></div>`;
    }
    ed.appendChild(wrap);
  });
}
function readUI(){
  state.docNo=$('docNo').value;
  state.docDate=$('docDate').value;
  state.billToName=$('billToName').value;
  state.billToInfo=$('billToInfo').value;
  state.billTo=[state.billToName,state.billToInfo].filter(Boolean).join('\n');
  state.poNumber=$('poNumber').value;
  state.doNumber=$('doNumber').value;
  state.deliveryTerm=$('deliveryTerm').value;
  state.paymentTerm=$('paymentTerm').value;
  state.delivery=Number($('delivery').value||0);
  state.notes=$('notes').value;
  state.receiptNormalText=$('receiptNormalText').value;
  state.receiptBoldText=$('receiptBoldText').value;
}

const QR_SRC="data:image/png;base64,";
function formatItemRows(items,startIndex,financial){
  return items.map((it,localIndex)=>{
    const i=startIndex+localIndex;
    if(financial){
      const amt=(Number(it.qty)||0)*(Number(it.unitPrice)||0);
      return `<tr><td class="no">${i+1}.</td><td class="desc">${esc(it.description)}</td><td class="qty">${Number(it.qty||0)}</td><td class="unit">${Number(it.unitPrice||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}</td><td class="amt">${Number(amt||0).toLocaleString('en-MY',{minimumFractionDigits:2,maximumFractionDigits:2})}</td></tr>`;
    }
    return `<tr><td class="no">${i+1}</td><td class="desc">${esc(it.description)}</td><td class="qty">${Number(it.qty||0)}</td></tr>`;
  }).join('');
}
function splitItems(items,size){
  const pages=[];
  for(let i=0;i<items.length;i+=size) pages.push({items:items.slice(i,i+size),start:i});
  return pages.length?pages:[{items:[],start:0}];
}
function invoiceNoteHtml(){
  const fallback='Thank you for your business.\nPlease make payment within 7 days of the invoice date.\nDo not hesitate to contact us if you have any questions regarding this invoice.';
  const raw=String(state.notes||fallback).replace(/\\n/g,'\n');
  let h='<div class="terms-flow"><p><strong>Note:</strong></p>';
  for(const line of raw.split(/\r?\n/)) h+=`<p>${esc(line)}</p>`;
  return h+'</div>';
}
function quotationNoteHtml(){
  const fallback='Validity 14 days from the quotation date.\nDelivery within 2 – 12 weeks.';
  const raw=String(state.notes||fallback).replace(/\\n/g,'\n');
  let h='<div class="terms-flow"><p><strong>Notes / Terms</strong></p>';
  for(const line of raw.split(/\r?\n/)) h+=`<p>${esc(line)}</p>`;
  return h+'</div>';
}
function paymentHtml(){
  return `<div class="bank"><strong>Bank Details:</strong><br>Bank Account: Bank Rakyat<br>Account No.: 1102064261<br>Account Name: THREE D LAB RESEARCH SOLUTIONS<br><br><strong>Touch N Go / DuitNow:</strong></div><div class="qr"><img src="${QR_SRC}" alt="DuitNow QR"></div>`;
}
function effectiveDelivery(){
  const input=document.getElementById('delivery');
  const value=Number(input ? input.value : state.sharedDelivery);
  const normalized=Number.isFinite(value)?value:0;
  state.delivery=normalized;
  state.sharedDelivery=normalized;
  for(const type of Object.keys(config)){
    if(!state.documents[type]) state.documents[type]=defaultDocument(type);
    state.documents[type].delivery=normalized;
  }
  return normalized;
}

function buildPage(pg,first,last,includeDetails=true){
  const t=state.type,c=config[t],financial=t!=='do';
  const allItems=state.items||[];
  const delivery=effectiveDelivery();
  state.delivery=delivery;
  const sub=allItems.reduce((a,it)=>a+(Number(it.qty)||0)*(Number(it.unitPrice)||0),0);
  const grand=sub+delivery;
  let content='<div class="doc">';
  content+=`<div class="doc-title">${c.title}</div>`;
  if(first){
    content+=`<div class="meta"><div class="billto"><div class="billto-label">Bill To:</div><div class="billto-name">${esc(state.billToName)}</div><div class="billto-info">${esc(state.billToInfo)}</div></div><div class="doc-meta"><div class="label">${c.label}</div><div class="colon">:</div><div>${esc(state.docNo)}</div><div class="label">${c.label} Date</div><div class="colon">:</div><div>${dateText(state.docDate)}</div></div></div>`;
    if(t==='invoice') content+=`<table class="rulebox"><thead><tr><th>P.O Number</th><th>D.O Number</th><th>Delivery Term</th><th>Payment Term</th></tr></thead><tbody><tr><td>${esc(state.poNumber)}</td><td>${esc(state.doNumber)}</td><td>${esc(state.deliveryTerm)}</td><td>${esc(state.paymentTerm)}</td></tr></tbody></table>`;
  } else {
    content+=`<div class="continuation-label">${esc(c.label)} — Continued</div>`;
  }
  if(t==='do'){
    content+=`<table class="items do-items"><thead><tr><th class="no">NO.</th><th class="desc">DESCRIPTION</th><th class="qty">QTY</th></tr></thead><tbody>${formatItemRows(pg.items,pg.start,false)}</tbody></table>`;
    if(last) content+=`<div class="signature-flow">Receiver Sign</div>`;
  } else {
    content+=`<table class="items"><thead><tr><th class="no">NO.</th><th class="desc">DESCRIPTION</th><th class="qty">QTY</th><th class="unit">UNIT PRICE (RM)</th><th class="amt">AMOUNT (RM)</th></tr></thead><tbody>${formatItemRows(pg.items,pg.start,true)}`;
    if(last){
      content+=`<tr><td colspan="3" class="summary-empty"></td><td class="summary-label">SUB-TOTAL</td><td class="summary-value">${money(sub)}</td></tr>`;
      content+=`<tr><td colspan="3" class="summary-empty"></td><td class="summary-label">DELIVERY</td><td class="summary-value">${money(delivery)}</td></tr>`;
      content+=`<tr><td colspan="3" class="summary-empty"></td><td class="summary-label grand-label">GRAND TOTAL</td><td class="summary-value grand-value">${money(grand)}</td></tr>`;
    }
    content+='</tbody></table>';
  }
  if(last && includeDetails){
    if(t==='receipt') content+=`<div class="details-flow"><div class="receipt-note">${esc(state.receiptNormalText||'')}<b>${esc(state.receiptBoldText||'')}</b></div></div>`;
    if(t==='quotation') content+=`<div class="details-flow">${quotationNoteHtml().replace('class="terms-flow"','class="terms-inline"')}${paymentHtml()}</div>`;
    if(t==='invoice') content+=`<div class="details-flow">${invoiceNoteHtml().replace('class="terms-flow"','class="terms-inline"')}${paymentHtml()}</div>`;
  }
  content+='</div>';
  return content;
}
function render(){
  updateFields();
  const p=$('paper');
  const items=Array.isArray(state.items)?state.items:[];
  const rowsPerPage = state.type==='do' ? 18 : 16;
  const pages=splitItems(items,rowsPerPage);

  const renderPages=(includeDetailsOnLast)=>{
    p.className='paper multi';
    p.innerHTML=pages.map((pg,i)=>`<div class="paper page-paper">${buildPage(pg,i===0,i===pages.length-1,includeDetailsOnLast)}</div>`).join('');
  };

  // First pass: keep the final details block on the last table page.
  renderPages(true);

  // If the notes/payment block would enter the footer-safe area, move the
  // entire details block to a new A4 page. This preserves the table on the
  // current page and prevents any overlap with the footer.
  const lastPage=p.querySelector('.page-paper:last-child');
  const details=lastPage?.querySelector('.details-flow');
  const doc=lastPage?.querySelector('.doc');
  if(details && doc){
    const detailBottom=details.getBoundingClientRect().bottom;
    const docBottom=doc.getBoundingClientRect().bottom;
    // 2mm safety margin above the footer boundary.
    const safety=2 * (window.devicePixelRatio || 1);
    if(detailBottom > docBottom - safety){
      renderPages(false);
      const detailsPage=`<div class="paper page-paper">${buildDetailsOnlyPage()}</div>`;
      p.insertAdjacentHTML('beforeend',detailsPage);
    }
  }
}

function buildDetailsOnlyPage(){
  const t=state.type;
  let content='<div class="doc">';
  const c=config[t];
  content+=`<div class="doc-title">${c.title}</div>`;
  content+=`<div class="continuation-label">${esc(c.label)} — Continued</div>`;
  if(t==='receipt'){
    content+=`<div class="details-flow"><div class="receipt-note">${esc(state.receiptNormalText||'')}<b>${esc(state.receiptBoldText||'')}</b></div></div>`;
  }else if(t==='quotation'){
    content+=`<div class="details-flow">${quotationNoteHtml().replace('class="terms-flow"','class="terms-inline"')}${paymentHtml()}</div>`;
  }else if(t==='invoice'){
    content+=`<div class="details-flow">${invoiceNoteHtml().replace('class="terms-flow"','class="terms-inline"')}${paymentHtml()}</div>`;
  }
  if(t==='do') content+=`<div class="signature-flow">Receiver Sign</div>`;
  content+='</div>';
  return content;
}

$('docType').addEventListener('change',()=>{
  const oldType=state.type;
  readUI();

  // Common information is shared across all document pages.
  // This prevents switching document type from clearing the customer/date/item information
  // already entered on the current page.
  const common={
    billToName:state.billToName||'',
    billToInfo:state.billToInfo||'',
    billTo:state.billTo||'',
    docDate:state.docDate||today(),
    delivery:Number(state.sharedDelivery||state.delivery||0)
  };
  const currentItems=JSON.parse(JSON.stringify(state.items||[]));

  saveCurrentDocument();

  const newType=$('docType').value;
  const targetBefore=state.documents[newType];
  const targetHadItemData=Array.isArray(targetBefore?.items) &&
    targetBefore.items.some(it=>String(it.description||'').trim() || Number(it.qty||0) || Number(it.unitPrice||0));

  restoreDocument(newType);

  // Keep shared customer/date data synchronized between pages.
  state.billToName=common.billToName;
  state.billToInfo=common.billToInfo;
  state.billTo=common.billTo;
  state.docDate=common.docDate;
  syncSharedDelivery(common.delivery);

  // When the destination page is still empty, carry over the item list as well.
  // Financial pages retain unit prices; Delivery Order uses description + quantity only.
  if(!targetHadItemData && currentItems.length){
    state.items=currentItems.map(it=>state.type==='do'
      ? {description:it.description||'',qty:Number(it.qty||0)}
      : {description:it.description||'',qty:Number(it.qty||0),unitPrice:Number(it.unitPrice||0)});
  }

  saveCurrentDocument();

  // Preserve document-number continuity without overwriting user-entered numbers.
  if(!state.docNo || state.docNo===config[newType].prefix){
    state.docNo=docPrefix(newType);
  }

  syncForm();
  render();
});

const syncAllFromDeliveryInput=()=>{
  const v=Number($('delivery').value||0);
  syncSharedDelivery(Number.isFinite(v)?v:0);
  saveCurrentDocument();
  syncForm();
  render();
};

['docNo','docDate','billToName','billToInfo','poNumber','doNumber','deliveryTerm','paymentTerm','notes','receiptNormalText','receiptBoldText'].forEach(id=>
  $(id).addEventListener('input',()=>{
    readUI();
    if(Number.isFinite(Number(state.sharedDelivery))) state.delivery=Number(state.sharedDelivery);
    saveCurrentDocument();
    render();
  })
);

// Delivery is a single shared field. Keep the sidebar value, shared state,
// every document state, and the live preview synchronized on both input and
// change events (including spinner/keyboard edits).
$('delivery').addEventListener('input',syncAllFromDeliveryInput);
$('delivery').addEventListener('change',syncAllFromDeliveryInput);

$('itemsEditor').addEventListener('input',e=>{
  const i=e.target.dataset.index, f=e.target.dataset.field;
  if(i==null) return;
  const index=Number(i);
  if(!Number.isInteger(index) || index<0) return;
  const value=f==='description'?e.target.value:Number(e.target.value||0);

  // Item data is shared across ALL document types. Update the active
  // state first, then propagate the change to every document.
  // IMPORTANT: do not rebuild the item editor on every keystroke, otherwise
  // the focused input is replaced and only one character can be entered.
  if(!Array.isArray(state.items)) state.items=[];
  while(state.items.length<=index){
    state.items.push(state.type==='do'
      ? {description:'',qty:0}
      : {description:'',qty:0,unitPrice:0});
  }
  if(f==='unitPrice' && state.type==='do') return;
  state.items[index][f]=value;

  readUI();
  for(const type of Object.keys(config)){
    const doc=state.documents[type] || (state.documents[type]=defaultDocument(type));
    if(!Array.isArray(doc.items)) doc.items=[];
    while(doc.items.length<=index){
      doc.items.push(type==='do'
        ? {description:'',qty:0}
        : {description:'',qty:0,unitPrice:0});
    }
    if(f==='unitPrice' && type==='do') continue;
    doc.items[index][f]=value;
  }

  // Keep the active state, all document states, and the preview synchronized.
  state.items=JSON.parse(JSON.stringify(state.documents[state.type].items));
  saveCurrentDocument();
  // Do NOT call renderItemsEditor() here: it would replace the input element
  // while the user is typing and steal focus after the first character.
  render();
});

$('itemsEditor').addEventListener('click',e=>{
  const i=e.target.dataset.remove;
  if(i==null) return;
  const index=Number(i);
  if(!Number.isInteger(index) || index<0) return;

  // Item rows are shared across all document types. Removing an item from
  // any document therefore removes the same row index from every document,
  // while leaving each document's own prices/other fields untouched.
  readUI();
  saveCurrentDocument();
  for(const type of Object.keys(config)){
    const doc=state.documents[type] || (state.documents[type]=defaultDocument(type));
    if(Array.isArray(doc.items) && index < doc.items.length){
      doc.items.splice(index,1);
    }
    if(!Array.isArray(doc.items) || !doc.items.length){
      doc.items=type==='do'
        ? [{description:'',qty:0}]
        : [{description:'',qty:0,unitPrice:0}];
    }
  }

  // Refresh the currently displayed document from the synchronized item list.
  const current=state.documents[state.type];
  state.items=JSON.parse(JSON.stringify(current.items));
  renderItemsEditor();
  render();
});

$('addItemBtn').addEventListener('click',()=>{
  // Add exactly ONE shared row. The previously incorrect logic used the
  // maximum item count across documents, which could cause one click to
  // create multiple rows when the document states had different lengths.
  readUI();
  saveCurrentDocument();

  const activeItems=Array.isArray(state.items) ? JSON.parse(JSON.stringify(state.items)) : [];
  const targetLength=activeItems.length;

  for(const type of Object.keys(config)){
    const doc=state.documents[type] || (state.documents[type]=defaultDocument(type));
    if(!Array.isArray(doc.items)) doc.items=[];

    // Keep all document pages at the same shared item count before adding.
    // The active document is the source of truth for the current shared list.
    if(doc.items.length>targetLength){
      doc.items=doc.items.slice(0,targetLength);
    }else{
      while(doc.items.length<targetLength){
        doc.items.push(type==='do'
          ? {description:'',qty:0}
          : {description:'',qty:0,unitPrice:0});
      }
    }

    doc.items.push(type==='do'
      ? {description:'',qty:0}
      : {description:'',qty:0,unitPrice:0});
  }

  state.items=JSON.parse(JSON.stringify(state.documents[state.type].items));
  renderItemsEditor();
  render();
});

$('newBtn').addEventListener('click',()=>{
  const type=$('docType').value;
  state.documents[type]=defaultDocument(type);
  restoreDocument(type);
  syncForm();
  render();
});

$('saveBtn').addEventListener('click',async()=>{
  readUI();
  saveCurrentDocument();
  const payload=JSON.parse(JSON.stringify(state));
  const filename=(state.docNo||'3D-Lab-document').replaceAll('/','-')+'.json';
  const json=JSON.stringify(payload,null,2);
  const blob=new Blob([json],{type:'application/json'});

  // Use the native Save As file picker when supported so the user can
  // choose the exact folder and filename instead of saving to Downloads.
  if('showSaveFilePicker' in window){
    try{
      const handle=await window.showSaveFilePicker({
        suggestedName:filename,
        types:[{
          description:'3D Lab Document Data',
          accept:{'application/json':['.json']}
        }]
      });
      const writable=await handle.createWritable();
      await writable.write(blob);
      await writable.close();
      return;
    }catch(err){
      // User cancelled the picker: do not trigger a second download.
      if(err && err.name==='AbortError') return;
      console.warn('Native save picker failed; falling back to browser download.',err);
    }
  }

  // Fallback for browsers/environments without the File System Access API.
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=filename;
  a.click();
  setTimeout(()=>URL.revokeObjectURL(a.href),1000);
});
$('loadBtn').addEventListener('click',()=>$('loadFile').click());
$('loadFile').addEventListener('change',e=>{
  const f=e.target.files[0];
  if(!f) return;
  const r=new FileReader();
  r.onload=()=>{
    try{
      const data=JSON.parse(r.result);
      Object.assign(state,data);
      if(!state.type || !config[state.type]) state.type='invoice';
      ensureDocumentStates();
      restoreDocument(state.type);
      syncForm();
      render();
    }catch(err){
      alert('Could not load this file. Please select a valid 3D Lab JSON data file.');
    }
  };
  r.readAsText(f);
  e.target.value='';
});
$('printBtn').addEventListener('click',()=>window.print());
$('downloadHtmlBtn').addEventListener('click',()=>{
  readUI(); render();
  const content=$('paper').outerHTML;
  const css=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n');
  const html=`<!doctype html><html><head><meta charset="utf-8"><title>${esc(state.docNo||'3D Lab Document')}</title><style>${css}</style></head><body>${content}<script>window.onload=()=>setTimeout(()=>window.print(),150);<\\/script></body></html>`;
  const blob=new Blob([html],{type:'text/html'}); const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download=(state.docNo||'3D-Lab-document').replaceAll('/','-')+'.html'; a.click(); setTimeout(()=>URL.revokeObjectURL(a.href),1000);
});
init();
